from __future__ import annotations

DASHBOARD_HTML = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width,initial-scale=1" />
<title>PCP Live Developer Console</title>
<style>
:root{color-scheme:dark;--bg:#080b12;--panel:#101620;--panel2:#0a1018;--border:#243044;--text:#edf2f7;--muted:#91a0b5;--accent:#6ee7b7;--blue:#60a5fa;--amber:#fbbf24;--red:#fb7185;--purple:#c084fc}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 15% -10%,#17233a 0,transparent 34%),var(--bg);font:14px/1.45 Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:var(--text)}a{color:#93c5fd;text-decoration:none}.wrap{max-width:1540px;margin:0 auto;padding:24px}.top{display:flex;gap:18px;align-items:center;justify-content:space-between;margin-bottom:18px}.eyebrow{color:var(--accent);font-size:11px;font-weight:800;letter-spacing:.14em;text-transform:uppercase}.title{font-size:27px;font-weight:760;letter-spacing:-.025em;margin:2px 0}.sub{color:var(--muted)}.pill{display:inline-flex;align-items:center;gap:7px;padding:7px 10px;border:1px solid var(--border);border-radius:999px;background:#0d131d;color:var(--muted);font-size:12px}.dot{width:8px;height:8px;border-radius:50%;background:var(--accent);box-shadow:0 0 14px var(--accent)}.dot.off{background:var(--red);box-shadow:none}.grid{display:grid;gap:14px}.summary{grid-template-columns:repeat(6,minmax(0,1fr));margin-bottom:14px}.card{background:linear-gradient(180deg,rgba(21,29,41,.94),rgba(12,17,26,.96));border:1px solid var(--border);border-radius:15px;padding:16px;box-shadow:0 15px 50px rgba(0,0,0,.18)}.k{font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.1em;font-weight:760}.v{font-size:25px;font-weight:760;margin-top:5px}.small{font-size:12px;color:var(--muted);margin-top:3px}.section{margin-bottom:14px}.section-head{display:flex;justify-content:space-between;gap:14px;align-items:flex-start;margin-bottom:12px}.section-title{font-size:16px;font-weight:730}.select{background:#0a1018;border:1px solid var(--border);color:var(--text);border-radius:9px;padding:7px 9px;max-width:420px}.status{display:inline-flex;border-radius:999px;padding:4px 8px;font-size:10px;font-weight:760;text-transform:uppercase;letter-spacing:.06em;border:1px solid}.s-running,.s-executing,.s-active,.s-planning,.s-routing,.s-verifying,.s-evaluating,.s-delivering{color:#93c5fd;border-color:#31598d;background:#102139}.s-completed,.s-sent{color:#86efac;border-color:#256548;background:#0e2b20}.s-awaiting_merge,.s-waiting_merge,.s-waiting_human{color:#fcd34d;border-color:#735b18;background:#2d250c}.s-blocked,.s-failed,.s-cancelled,.s-interrupted{color:#fda4af;border-color:#7f3342;background:#30131a}.s-pending,.s-queued{color:#c4b5fd;border-color:#5a4684;background:#211936}.pipeline{display:flex;gap:8px;overflow:auto}.step{min-width:210px;flex:1;border:1px solid var(--border);border-radius:11px;padding:11px;background:var(--panel2)}.step.current{border-color:#3f6fa8}.step .name{font-weight:670;margin:4px 0 8px;word-break:break-word}.console{background:#05080d;border:1px solid #1e2a3b;border-radius:12px;height:min(58vh,720px);min-height:390px;overflow:auto;padding:10px 0;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}.console-empty{color:#65758c;padding:24px;text-align:center}.log{display:grid;grid-template-columns:78px 72px minmax(0,1fr);gap:9px;padding:7px 12px;border-bottom:1px solid rgba(36,48,68,.42)}.log:hover{background:#0b111a}.log-time{color:#65758c;font-size:11px}.log-kind{font-size:10px;font-weight:800;letter-spacing:.08em}.kind-DEV{color:var(--accent)}.kind-TOOL{color:var(--blue)}.kind-OK{color:#86efac}.kind-ERR{color:var(--red)}.kind-EDIT{color:var(--purple)}.log-main{min-width:0;white-space:pre-wrap;word-break:break-word;color:#d9e2ee}.log-output{margin-top:5px;padding:7px 9px;border-left:2px solid #27364b;background:#080d14;color:#9fb0c4;white-space:pre-wrap;max-height:180px;overflow:auto}.below{grid-template-columns:minmax(0,1.55fr) minmax(330px,.75fr);align-items:start}.metrics{grid-template-columns:repeat(4,minmax(0,1fr))}.metric{border:1px solid var(--border);border-radius:11px;padding:12px;background:var(--panel2)}.metric .mv{font-size:19px;font-weight:720;margin-top:4px}.models{grid-template-columns:repeat(3,minmax(0,1fr))}.model{border:1px solid var(--border);background:var(--panel2);border-radius:10px;padding:11px}.model.active{border-color:#3e8c73}.timeline{max-height:420px;overflow:auto;margin-top:10px}.event{border-left:1px solid #2a394d;margin-left:5px;padding:0 0 13px 15px}.event b{font-size:12px}.event .meta{font-size:10px;color:var(--muted)}.alert{padding:10px 0;border-bottom:1px solid #1c2737}.login{position:fixed;inset:0;background:rgba(3,6,12,.9);backdrop-filter:blur(12px);display:none;align-items:center;justify-content:center;z-index:20}.login.show{display:flex}.login-box{width:min(420px,calc(100vw - 34px));background:#0f1622;border:1px solid var(--border);border-radius:17px;padding:24px}.login-box input{width:100%;margin:16px 0 10px;background:#080d15;border:1px solid #334158;color:white;border-radius:10px;padding:12px}.login-box button{border:0;border-radius:10px;padding:11px 14px;background:#e7f7f1;color:#062219;font-weight:760;cursor:pointer}.err{color:#fda4af;font-size:12px;min-height:18px;margin-top:8px}.foot{font-size:11px;color:#718096;margin-top:12px}@media(max-width:1050px){.summary{grid-template-columns:repeat(3,1fr)}.below{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,1fr)}}@media(max-width:640px){.wrap{padding:14px}.top{align-items:flex-start;flex-direction:column}.summary{grid-template-columns:repeat(2,1fr)}.metrics,.models{grid-template-columns:1fr}.log{grid-template-columns:62px 54px minmax(0,1fr)}.console{height:55vh}}
</style>
</head>
<body>
<div class="login" id="login"><div class="login-box"><div class="eyebrow">Read-only access</div><h2>Developer console</h2><div class="sub">Enter DASHBOARD_READ_TOKEN. The token is exchanged for an HttpOnly session cookie.</div><input id="token" type="password" autocomplete="current-password" placeholder="Dashboard read token" /><button id="loginBtn">Open dashboard</button><div class="err" id="loginErr"></div></div></div>
<div class="wrap">
<div class="top"><div><div class="eyebrow">Personal Coding Platform</div><div class="title">Live Developer Console</div><div class="sub" id="subtitle">Connecting…</div></div><div class="pill"><span class="dot" id="streamDot"></span><span id="connection">connecting</span></div></div>
<div class="grid summary" id="summary"></div>
<section class="card section"><div class="section-head"><div><div class="section-title">Execution plan</div><div class="small" id="planMeta">—</div></div><select id="planSelect" class="select"></select></div><div id="pipeline" class="pipeline"></div></section>
<section class="card section" id="standaloneCard" style="display:none"><div class="section-head"><div><div class="section-title">Standalone jobs</div><div class="small" id="standaloneMeta">Direct Runtime jobs outside ExecutionPlans</div></div><select id="standaloneSelect" class="select"></select></div></section>
<section class="card section"><div class="section-head"><div><div class="section-title">Developer transcript</div><div class="small">Live, replayable, sanitized model/tool activity · raw chain-of-thought and secrets are never exposed</div></div><div id="jobStatus"></div></div><div id="console" class="console"><div class="console-empty">Waiting for an agent job…</div></div></section>
<div class="grid below"><div><section class="card section"><div class="section-head"><div><div class="section-title">Current job telemetry</div><div class="small" id="jobMeta">No active job</div></div></div><div class="grid metrics" id="metrics"></div></section><section class="card section"><div class="section-title">Model assignment</div><div class="grid models" id="models" style="margin-top:10px"></div></section></div><aside><section class="card section"><div class="section-title">Execution timeline</div><div class="small">High-level durable state transitions · newest first</div><div id="timeline" class="timeline"></div></section><section class="card section"><div class="section-title">Recent alerts</div><div id="alerts"></div></section></aside></div>
<div class="foot">Read-only observability. Dashboard disconnects never control, pause, resume, or otherwise affect a coding job.</div>
</div>
<script>
const $=s=>document.querySelector(s);let snapshot=null,selected=null,selectedStandalone=null,source=null,streamJob=null,lastSeq=0,consoleEvents=[];const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));const fmt=n=>Intl.NumberFormat('en',{notation:Number(n)>=1e6?'compact':'standard',maximumFractionDigits:1}).format(Number(n||0));const status=s=>`<span class="status s-${esc(s)}">${esc(s||'unknown')}</span>`;
function showLogin(msg=''){ $('#login').classList.add('show');$('#loginErr').textContent=msg }function hideLogin(){ $('#login').classList.remove('show');$('#loginErr').textContent='' }async function login(){const r=await fetch('/v1/dashboard/session',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({token:$('#token').value})});if(!r.ok){showLogin(r.status===503?'Dashboard token is not configured.':'Invalid dashboard token.');return}$('#token').value='';hideLogin();await refresh()}$('#loginBtn').onclick=login;$('#token').addEventListener('keydown',e=>{if(e.key==='Enter')login()});
function currentPlan(){if(!snapshot?.plans?.length)return null;return snapshot.plans.find(p=>p.id===selected)||snapshot.plans.find(p=>p.id===snapshot.current_plan_id)||snapshot.plans[0]}function currentWO(p){return p?.work_orders?.find(w=>w.lifecycle!=='superseded'&&['running','awaiting_merge','waiting_human'].includes(w.state))||p?.work_orders?.find(w=>w.lifecycle!=='superseded'&&w.job&&['queued','routing','planning','executing','verifying','evaluating','delivering','blocked','failed','interrupted'].includes(w.job.status))||null}function currentStandalone(){const jobs=snapshot?.standalone_jobs||[];return selectedStandalone?jobs.find(j=>j.id===selectedStandalone)||null:null}
function summaryCards(s){const d=[['Active plans',s.active_plans],['Active jobs',s.active_jobs],['Standalone',s.standalone_jobs],['Merge gates',s.waiting_merge],['Human gates',s.waiting_human],['Blocked',s.blocked_plans],['Superseded',s.superseded_plans],['Outbox',s.pending_notifications]];$('#summary').innerHTML=d.map(x=>`<div class="card"><div class="k">${x[0]}</div><div class="v">${fmt(x[1])}</div></div>`).join('')}
function renderPicker(){const ps=snapshot.plans||[];if(!selected)selected=snapshot.current_plan_id||ps[0]?.id||null;$('#planSelect').innerHTML=ps.map(p=>`<option value="${esc(p.id)}" ${p.id===selected?'selected':''}>${esc(p.id)} · ${esc(p.lifecycle==='superseded'?'superseded':p.status)}</option>`).join('');$('#planSelect').onchange=e=>{selected=e.target.value;selectedStandalone=null;render()}}function renderStandalonePicker(){const jobs=snapshot.standalone_jobs||[],card=$('#standaloneCard'),select=$('#standaloneSelect');if(!jobs.length){card.style.display='none';selectedStandalone=null;return}card.style.display='';if(selectedStandalone&&!jobs.some(j=>j.id===selectedStandalone))selectedStandalone=null;const p=currentPlan(),w=currentWO(p);if(!selectedStandalone&&!w)selectedStandalone=jobs[0].id;select.innerHTML='<option value="">Follow execution plan</option>'+jobs.map(j=>`<option value="${esc(j.id)}" ${j.id===selectedStandalone?'selected':''}>${esc(j.project_id||'project')} · ${esc(j.id)} · ${esc(j.status)}</option>`).join('');$('#standaloneMeta').textContent=`${jobs.length} direct/runtime job${jobs.length===1?'':'s'} outside ExecutionPlans`;select.onchange=e=>{selectedStandalone=e.target.value||null;render()}}
function renderPipeline(p){if(!p){$('#pipeline').innerHTML='<div class="small">No orchestrated plans.</div>';return}const planState=p.lifecycle==='superseded'?'superseded':p.status;$('#planMeta').innerHTML=`${esc(p.project_id)} · ${esc(p.ticket_id||'')} · ${status(planState)} · baseline ${esc(p.baseline_revision||'—')}`;$('#pipeline').innerHTML=(p.work_orders||[]).map((w,i)=>{const workState=w.lifecycle==='superseded'?'superseded':w.state,replacement=w.superseded_by_work_order_id?`<div class="small">replaced by ${esc(w.superseded_by_work_order_id)}</div>`:'',history=w.lifecycle==='superseded'&&w.job?`<div class="small">${esc(w.job.id)} · ${esc(w.job.status)} · ${esc(w.job.result_reason||'')}</div>`:'';return `<div class="step ${p.current_work_order_id===w.id?'current':''}"><div class="k">STEP ${i+1} · ${esc(w.execution_mode)}</div><div class="name">${esc(w.id)}</div>${status(workState)}${replacement}${history}</div>`}).join('')}
function metric(k,v,sub=''){return `<div class="metric"><div class="k">${k}</div><div class="mv">${esc(v)}</div><div class="small">${esc(sub)}</div></div>`}function renderJob(w){const j=w?.job;if(!j){$('#jobMeta').textContent='No active job';$('#jobStatus').innerHTML='';$('#metrics').innerHTML='';$('#models').innerHTML='';connectStream(null);return}$('#jobMeta').textContent=`${j.id} · ${w.id} · ${j.branch||'branch pending'}`;$('#jobStatus').innerHTML=status(j.status);const p=j.progress||{},b=j.budget||{},r=j.remaining||{};$('#metrics').innerHTML=[metric('Elapsed',`${Number(p.elapsed_minutes||0).toFixed(1)}m`,`remaining ${r.wall_time_minutes??'—'}m`),metric('Model calls',p.model_calls||0,`remaining ${r.model_calls??'—'}`),metric('Tool calls',p.tool_calls||0,`tests ${p.test_runs||0}`),metric('Changed files',p.changed_files||0,`limit ${b.max_changed_files||'—'}`),metric('Repairs',p.repair_iterations||0,`remaining ${r.repair_iterations??'—'}`),metric('Failovers',`${p.provider_failovers||0}/${p.model_failovers||0}`,'provider / model'),metric('Output tokens',fmt(j.tokens?.output_tokens||0),`input ${fmt(j.tokens?.input_budget_tokens||0)}`),metric('Checks',p.required_checks_passed?'PASS':p.tests_passed?'tests pass':'pending')].join('');const ms=j.models||{};$('#models').innerHTML=['planner','executor','evaluator'].map(role=>{const m=ms[role],active=ms.current&&m&&ms.current.id===m.id;return `<div class="model ${active?'active':''}"><div class="k">${role}${active?' · current':''}</div><div style="font-weight:720;margin-top:5px">${esc(m?.id||'—')}</div><div class="small">${esc(m?.model||'')}${m?.reasoning_effort?' · '+esc(m.reasoning_effort):''}</div></div>`}).join('');const replay=[...(j.recent_events||[])].filter(e=>String(e.event||'').startsWith('developer_')).sort((a,b)=>Number(a.seq)-Number(b.seq));if(streamJob!==j.id){consoleEvents=replay.slice(-200);lastSeq=consoleEvents.reduce((m,e)=>Math.max(m,Number(e.seq||0)),0);renderConsole();connectStream(j.id)}}
function kind(e){if(e.event==='developer_message')return 'DEV';if(e.event==='developer_file_activity')return 'EDIT';if(e.event==='developer_error'||e.level==='error')return 'ERR';if(e.event==='developer_command_completed')return e.data?.exit_code===0||e.level==='success'?'OK':'ERR';return 'TOOL'}function renderConsole(){const el=$('#console');if(!consoleEvents.length){el.innerHTML='<div class="console-empty">No developer transcript yet. The next Codex model/tool event will appear here live.</div>';return}el.innerHTML=consoleEvents.map(e=>{const k=kind(e),d=e.data||{},out=d.output?`<div class="log-output">${esc(d.output)}</div>`:'';return `<div class="log"><div class="log-time">${esc(new Date(e.timestamp).toLocaleTimeString())}</div><div class="log-kind kind-${k}">${k}</div><div class="log-main">${esc(e.message)}${out}</div></div>`}).join('');el.scrollTop=el.scrollHeight}
function pushEvent(e){const seq=Number(e.seq||0);if(seq&&consoleEvents.some(x=>Number(x.seq)===seq))return;if(String(e.event||'').startsWith('developer_')){consoleEvents.push(e);consoleEvents=consoleEvents.slice(-200);renderConsole()}lastSeq=Math.max(lastSeq,seq)}function setStreamState(text,ok){$('#connection').textContent=text;$('#streamDot').classList.toggle('off',!ok)}function connectStream(jobId){if(source){source.close();source=null}streamJob=jobId;if(!jobId){setStreamState('snapshot only',true);return}source=new EventSource(`/v1/dashboard/jobs/${encodeURIComponent(jobId)}/stream?after=${lastSeq}`);source.addEventListener('activity',ev=>{try{pushEvent(JSON.parse(ev.data));setStreamState('live stream',true)}catch(_){}});source.onopen=()=>setStreamState('live stream',true);source.onerror=()=>setStreamState('reconnecting…',false)}
function renderTimeline(w){const ev=[...(w?.job?.recent_events||[])].filter(e=>!String(e.event||'').startsWith('developer_')).sort((a,b)=>Number(b.seq)-Number(a.seq));$('#timeline').innerHTML=ev.length?ev.map(e=>`<div class="event"><b>${esc(e.message)}</b><div class="meta">${esc(new Date(e.timestamp).toLocaleTimeString())} · ${esc(e.phase)}</div></div>`).join(''):'<div class="small">No timeline events.</div>'}function renderAlerts(){const a=(snapshot.alerts||[]).slice(0,3);$('#alerts').innerHTML=a.length?a.map(x=>`<div class="alert"><b>${esc(x.event_type)}</b> ${status(x.status)}<div class="small">${esc(x.summary)}</div></div>`).join(''):'<div class="small">No notifications.</div>'}
function render(){summaryCards(snapshot.summary||{});renderPicker();renderStandalonePicker();const p=currentPlan(),w=currentWO(p),standalone=currentStandalone(),display=standalone?{id:'standalone',job:standalone}:w;renderPipeline(p);renderJob(display);renderTimeline(display);renderAlerts();$('#subtitle').textContent=`Updated ${new Date(snapshot.generated_at).toLocaleTimeString()} · ${snapshot.plans?.length||0} plans · ${snapshot.standalone_jobs?.length||0} standalone jobs`}
async function refresh(){try{const r=await fetch('/v1/dashboard/snapshot',{cache:'no-store'});if(r.status===401){if(source)source.close();showLogin();return}if(r.status===503){showLogin('Dashboard token is not configured.');return}if(!r.ok)throw new Error(`HTTP ${r.status}`);snapshot=await r.json();hideLogin();render()}catch(e){setStreamState('snapshot disconnected',false);console.error(e)}}refresh();setInterval(refresh,3000);
</script>
</body></html>'''
